theme_fields.value:
.pill {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
  flex-direction: column;
  -webkit-box-pack: center;
  justify-content: center;
  width: stretch;
  min-height: -webkit-fill-available;
  position: -webkit-sticky;
  position: sticky;
  transition: transform .3s ease, backdrop-filter .2s;
  backdrop-filter: blur(4px);
  user-select: none;
  background: -webkit-linear-gradient(top, red, blue);
  background: linear-gradient(to bottom, red, blue);
  &::-moz-selection { color: red; }
  &::selection { color: red; }
}
.clamp { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; }
::-webkit-input-placeholder { color: gray; }
::placeholder { color: gray; }
@-webkit-keyframes pulse { from { opacity: 0; } }
@keyframes pulse { from { opacity: 0; } to { opacity: 1; } }
@supports (backdrop-filter: blur(1px)) {
  .glass { background: rgba($secondary, .5); }
}
@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi) {
  .hd { background-image: image-set(url(a.png) 1x, url(b.png) 2x); }
}
.mode {
  text-size-adjust: light-dark(100%, 90%);
  box-decoration-break: clone;
  text-decoration: underline dotted;
  hyphens: auto;
  cursor: -webkit-grab;
  cursor: grab;
}
@font-face {
  font-family: Prefixed;
  --face-color: light-dark(#{$primary}, #{$secondary});
}
